func TestB4AcceptRangesAParameterAfterTheWeightIsInvalid(t *testing.T) {
	made0, err := AcceptParse([]string{"Text/HTML; Level=1; Q=0.5; x=y, */*"})
	if err == nil {
		_, err = made0.Ranges()
	}
	failure, ok := err.(*liberrors.HTTPNegotiationValueError)
	if !ok || failure.Kind() != "invalid_accept" {
		t.Fatalf("B-4: %#v", err)
	}
	if status, ok := failure.Status(); !ok || status != 400 {
		t.Fatalf("B-4: the status of %#v", err)
	}
	if _, ok := failure.Errno(); ok {
		t.Fatalf("B-4: the errno of %#v", err)
	}
}

